import React, { memo, useState, useCallback, useEffect } from 'react'
import { useDispatch, useSelector } from 'react-redux'

import './GroupPlayerEdit.scss'
import {
	GROUP_TYPE_OLYMPIC_PLUS,
	GROUP_TYPE_RR,
	GROUP_TYPE_NOPLAYER,
	GROUP_TYPE_OLYMPIC,
	GROUP_TYPE_OLYMPIC_THREE,
	GROUP_TYPE_DROP_OUT
} from '../../utils/constants'
import { ReactComponent as ArrowDownIcon } from '../../icons/arrow_down.svg'
import { ReactComponent as RemoveIcon } from '../../icons/remove.svg'
import { ReactComponent as BucketIcon } from '../../icons/bucket.svg'
import { ReactComponent as PlusWhiteIcon } from '../../icons/plus_white.svg'
import { updateGroup } from '../../redux/stageService/stageSlice'
import { ReactComponent as RoundRobinIcon } from '../../icons/round_robin.svg'
import { removeGroup } from '../../redux/stageService/stageSlice'
import { ReactComponent as OlympicPlusIcon } from '../../icons/olympic_plus.svg'
import { ReactComponent as NoPlayerIcon } from '../../icons/no_player.svg'
import { ReactComponent as OlympicThreeIcon } from '../../icons/olympic_three.svg'
import { ReactComponent as OlympicIcon } from '../../icons/olympic.svg'
import { ReactComponent as DropOut } from '../../icons/drop_out.svg'
import RadioButton from '../../reusableComponents/RadioButton/RadioButton'
import Button from '../../reusableComponents/Button/Button'
import Popup from '../../reusableComponents/Popup/Popup'

import { selectStage } from '../../redux/selectors'

const groupTypeArray = [
	{
		type: GROUP_TYPE_RR,
		name: 'Круговая',
		icon: <RoundRobinIcon className="round-robin__icon" />
	},
	{
		type: GROUP_TYPE_OLYMPIC_PLUS,
		name: 'Олимпийская+',
		icon: <OlympicPlusIcon className="olympic-plus__icon" />
	},
	{
		type: GROUP_TYPE_OLYMPIC,
		name: 'Олимпийская',
		icon: <OlympicIcon className="olympic__icon" />
	},
	{
		type: GROUP_TYPE_OLYMPIC_THREE,
		name: 'Олимпийская3',
		icon: <OlympicThreeIcon className="olympic-three__icon" />
	},
	{
		type: GROUP_TYPE_NOPLAYER,
		name: 'Проходная',
		icon: <NoPlayerIcon className="no-player__icon" />
	},
	{
		type: GROUP_TYPE_DROP_OUT,
		name: 'Вылет',
		icon: <DropOut className="dropout__icon" />
	}
]

function GroupPlayerEdit({ levelIndex, groupIndex, group }) {
	const dispatch = useDispatch()
	const stageData = useSelector(selectStage)
	const { levels } = stageData

	const [count, setCount] = useState(group?.participants_max)
	const [typeGroup, setTypeGroup] = useState(groupTypeArray.find(item => item.type === group.type))
	const [changeTypeGroup, setChangeTypeGroup] = useState(typeGroup)
	const [openedGroupTypeEdition, setOpenedGroupTypeEdition] = useState(false)

	const handleMinus = useCallback(() => {
		if (count === 1) {
			return
		} else {
			setCount(prev => --prev)
		}
	}, [count])

	const handlePlus = useCallback(() => {
		setCount(prev => ++prev)
	}, [])

	useEffect(() => {
		dispatch(updateGroup({
			levelIndex: levelIndex,
			groupIndex: groupIndex,
			participantsMax: count,
			type: typeGroup?.type
		}))
	}, [levelIndex, groupIndex, count, typeGroup, dispatch])

	const handleRemoveGroup = useCallback(() => {
		dispatch(removeGroup({
			levels,
			levelIndex,
			groupIndex
		}))
	}, [dispatch, levelIndex, groupIndex, levels])

	const handleGroupTypeChange = useCallback((e) => {
		setChangeTypeGroup(groupTypeArray.find(item => item.type === e.target.value))
	}, [])

	const switchGroupType = useCallback((type) => {
		setTypeGroup(groupTypeArray.find(item => item.type === type))
	}, [])

	return (
		<>
			<div className="change-group__wrapper">
				<button
					className="change-group-type__wrapper"
					onClick={() => setOpenedGroupTypeEdition(true)}
				>
					{typeGroup.icon}

					<p className="change-group-type__text">
						{typeGroup.name}
					</p>

					<ArrowDownIcon className="arrow-down__icon" />
				</button>

				<div className="counter-groupe__wrapper">
					<button
						className="counter-groupe__button"
						onClick={() => handleMinus()}
					>
						<RemoveIcon className="remove-icon" />
					</button>

					<p className="counter-groupe__text">
						{count}
					</p>

					<button
						className="counter-groupe__button"
						onClick={() => handlePlus()}
					>
						<PlusWhiteIcon className="plus-white__icon" />
					</button>
				</div>
			</div>

			<button
				className="delete-group__wrapper"
				onClick={() => handleRemoveGroup()}
			>
				<BucketIcon className="bucket__icon" />

				Удалить группу
			</button>

			{
				openedGroupTypeEdition &&
				<Popup title="Тип группы">
					{
						groupTypeArray?.map((item, index) => (
							<RadioButton
								borderTop={index === 0}
								borderBottom
								key={index}
								name={'group'}
								id={`group-${index}`}
								label={item.name}
								value={item.type}
								checked={item.type === changeTypeGroup.type}
								onChange={handleGroupTypeChange}
							/>
						))
					}

					<div className="group-players__popup-buttons">
						<Button
							title="Выбрать"
							onClick={() => {
								switchGroupType(changeTypeGroup.type)
								setOpenedGroupTypeEdition(false)
							}}
							marginRight
						/>

						<Button
							title="Отмена"
							onClick={() => setOpenedGroupTypeEdition(false)}
							background={'white'}
						/>
					</div>
				</Popup>
			}
		</>
	)
}

export default memo(GroupPlayerEdit)