import React, { useEffect, useRef, useState } from 'react'
import { Route, Routes, useParams } from 'react-router'
import { useSelector, useDispatch } from 'react-redux'

import { selectTournament } from '../../redux/selectors'
import { setPlayersList, setStageData } from '../../redux/stageService/stageSlice'
import StageForm from '../StageForm/StageForm'
import PreStageRating from '../PreStageRating/PreStageRating'
import { formLevels, formNodes } from '../../utils/functions'
import StageBuild from '../StageBuild/StageBuild'
import StageGeneration from '../StageGeneration/StageGeneration'

function StageStructure({
	preStage,
	stage,
	setStageExists,
	setStageStatus,
	tournamentRefetch,
	stageStatus,
	stageExists
}) {
	const dispatch = useDispatch()
	const params = useParams()
	const { stageNumber } = params
	const { type, players, doubles, uid } = useSelector(selectTournament)
	const immutableLevels = useRef()
	const [initialParticipantsPreStage, setInitialParticipantsPreStage] = useState([])

	useEffect(() => {
		if (stage !== null && Object.keys(stage).length !== 0) {
			const { levels, rating_initial } = stage

			// Формируем уровень
			const formedLevels = formLevels(levels, players || doubles, type, stageNumber, stage)
			// Формируем игроков
			const formedNodes = formNodes(rating_initial, players || doubles, type, stage)

			dispatch(setPlayersList(formedNodes))
			const stageState = { ...stage, levels: formedLevels }
			dispatch(setStageData(stageState))

			immutableLevels.current = formedLevels

			setInitialParticipantsPreStage(formedNodes)
		}
	}, [stage, stageNumber, type, doubles, players, dispatch])

	return (
		<React.Fragment>
			<Routes>
				<Route path="/" element={
					<StageForm
						stage={stage}
						immutableLevels={immutableLevels}
						setStageExists={setStageExists}
						setStageStatus={setStageStatus}
						tournamentRefetch={tournamentRefetch}
						stageExists={stageExists}
						stageStatus={stageStatus}
					/>
				} />

				<Route path="build" element={
					<StageBuild
						stage={stage}
						immutableLevels={immutableLevels}
						setStageExists={setStageExists}
						setStageStatus={setStageStatus}
						tournamentRefetch={tournamentRefetch}
						stageExists={stageExists}
						stageStatus={stageStatus}
					/>
				} />

				<Route path="/generation" element={
					<StageGeneration
						stage={stage}
						tournamentUid={uid}
						tournamentRefetch={tournamentRefetch}
						setStageExists={setStageExists}
						setStageStatus={setStageStatus}
					/>
				} />

				<Route path="/pre-stage" element={
					<PreStageRating
						initialParticipantsPreStage={initialParticipantsPreStage}
						setInitialParticipantsPreStage={setInitialParticipantsPreStage}
						preStage={preStage}
					/>
				} />
			</Routes>
		</React.Fragment>
	)
}

export default StageStructure