import { TYPE_DOUBLES, NODE_TYPE_IN } from '../../utils/constants'
import { getNewUid } from '../../utils/functions'

export function dragItems(result, levels) {
	const [sourceLevelIndex, sourceGroupIndex] = result.source.droppableId.split('-')
	const [endLevelIndex, endGroupIndex] = result.destination.droppableId.split('-')

	const movedNode = {
		...levels[sourceLevelIndex]?.groups[sourceGroupIndex]?.nodes[result.source.index],
	}
	const replacedNode = {
		...levels[endLevelIndex]?.groups[endGroupIndex]?.nodes[result.destination.index]
	}

	const updatedMovedNode = {
		...movedNode,
		name: replacedNode.name,
		participant: replacedNode.participant,
		playerUid: replacedNode.playerUid,
		doubleUid: replacedNode.doubleUid,
		dependsOnUid: replacedNode.dependsOnUid,
		rating: replacedNode.rating
	}

	const updatedReplacedNode = {
		...replacedNode,
		name: movedNode.name,
		participant: movedNode.participant,
		playerUid: movedNode.playerUid,
		doubleUid: movedNode.doubleUid,
		dependsOnUid: movedNode.dependsOnUid,
		rating: movedNode.rating
	}

	return {
		sourceLevelIndex,
		endLevelIndex,
		endGroupIndex,
		sourceGroupIndex,
		endIndex: result.destination.index,
		sourceIndex: result.source.index,
		movedNode: updatedMovedNode,
		replacedNode: updatedReplacedNode
	}
}

export function formNodesForRequest(stage, editedLevels, type) {
	const startNodes = []
	const editedNodes = []

	stage?.levels?.forEach(lvl => {
		lvl?.groups?.forEach(grp => {
			grp?.nodes?.forEach(n => {
				if (n?.type === NODE_TYPE_IN) {
					startNodes.push(n)
				}
			})
		})
	})

	editedLevels?.forEach(lvl => {
		lvl?.groups?.forEach(grp => {
			grp?.nodes?.forEach(n => {
				editedNodes.push(n)
			})
		})
	})

	const nodes = {
		nodes: []
	}

	startNodes?.forEach((startN, index) => {
		const editedNode = editedNodes[index]
		if (type === TYPE_DOUBLES) {
			nodes.nodes.push({ uid: startN.uid, double_uid: editedNode.doubleUid })
		} else {
			nodes.nodes.push({ uid: startN.uid, player_uid: editedNode.playerUid })
		}
	})

	console.log(nodes)

	return nodes
}

function updateNodesList(levels, currentList) {
	const placedPlayers = []

	levels?.forEach(lvl => {
		lvl?.groups?.forEach(grp => {
			grp?.nodes?.forEach(n => {
				placedPlayers?.push({ ...n, groupName: grp?.name })
			})
		})
	})

	const updatedNodesList = currentList?.map(item => {
		const found = placedPlayers?.find(p => p?.nodeUid === item?.nodeUid)

		if (found) {
			return { ...item, groupName: found?.groupName }
		} else {
			return { ...item, groupName: null }
		}
	})

	return updatedNodesList
}

function cleanNodesInGroups(levels) {
	return levels?.map(lvl => {
		return {
			...lvl,
			groups: lvl?.groups?.map(grp => {
				return {
					...grp,
					nodes: grp?.nodes?.map(n => ({
						...n,
						placed: false,
						name: '---',
						nodeUid: getNewUid(),
						playerUid: null,
						doubleUid: null,
						rating: '-',
						emptyPlayer: true,
					})),
				}
			}),
		}
	})
}

function checkNodes(levels, levelsMemory) {
	for (let i = 0; i < levelsMemory?.length; i++) {
		const rememberedLevel = levelsMemory[i]
		const currentLevel = levels.find(level => level.name === rememberedLevel.name)

		// Если Уровень из levels отсутствует в levelsMemory, пропускаем ее
		if (!currentLevel) continue

		const matchingGroups = rememberedLevel.groups.filter(currentGroup => {
			// Проверяем, есть ли группа с таким же названием в currentLevel.groups
			return currentLevel.groups.some(rememberedGroup => rememberedGroup.name === currentGroup.name)
		})

		for (let b = 0; b < currentLevel.groups?.length; b++) {
			for (let c = 0; c < matchingGroups[b]?.nodes?.length; c++) {
				const node1 = currentLevel.groups[b].nodes[c]
				const node2 = matchingGroups[b].nodes[c]

				if (
					node1.playerUid !== node2.playerUid
					|| node1.doubleUid !== node2.doubleUid || node1.name !== node2.name
				) {
					return true
				}
			}
		}

		return false
	}
}

function checkLevelsAndGroups(levels, levelsMemory) {
	const levelsMemoryLength = levelsMemory.length
	const levelsLength = levels.length

	const groupMemory = levelsMemory.map(level => {
		return level.groups
	})
	const groupMemoryLength = groupMemory[0].length

	const group = levels.map(level => {
		return level.groups
	})
	const groupLength = group[0].length

	if ((levelsMemoryLength !== levelsLength) || (groupMemoryLength !== groupLength)) {
		return true
	} else {
		let isDifferent = false

		levelsMemory.forEach((groups, groupsIndex) => {
			groups.groups.forEach((group, groupIndex) => {
				if ((group?.participants_max !== levels[groupsIndex].groups[groupIndex]?.participants_max) || (group.type !== levels[groupsIndex].groups[groupIndex].type)) {
					isDifferent = true
				}
			})
		})

		return isDifferent
	}
}

function cleanPlacedAttribute(participantsList) {
	return participantsList.map((item) => {
		return {
			...item,
			placed: false
		}
	})
}

export {
	updateNodesList,
	cleanPlacedAttribute,
	checkLevelsAndGroups,
	checkNodes,
	cleanNodesInGroups
}