import { useEffect, useState } from 'react'

import { FULFILLED } from '../utils/constants'

function useProcessStageData(stageData, status) {
	const [stage, setStage] = useState(null)
	const [stageStatus, setStageStatus] = useState('create')
	const [stageExists, setStageExists] = useState(false)

	useEffect(() => {
		if (status !== FULFILLED) {
			return
		}

		if (Object.keys(stageData).length !== 0) {
			setStageExists(true)
			if (stageData.levels.length > 0) {
				setStage(stageData)
				setStageStatus('filled')
			} else {
				setStage(stageData)
				setStageStatus('generate')
			}
		} else {
			setStageStatus('create')
			setStageExists(false)
		}
	}, [stageData, status])

	return { stage, stageStatus, stageExists, setStageExists, setStageStatus }
}

export { useProcessStageData }