import { createSlice } from '@reduxjs/toolkit'

import { EMPTY_NODE } from '../../utils/constants'
import { getLocalStorageItem, getNewUid, setItemInLocalStorage, updateGroupsAndLevelsOrderNumber } from '../../utils/functions'

const stageSlice = createSlice({
	name: 'stage',
	initialState: {
		stage: {},
		playersList: [],
		chosenPlayerInList: {},
		dragState: {},
		currentStageNumber: getLocalStorageItem('currentStage') || 1
	},
	reducers: {
		setStageData(state, action) {
			state.stage = action.payload
		},
		addParticipant(state, action) {
			const { levelIndex, groupIndex, node } = action.payload
			state.stage.levels[levelIndex].groups[groupIndex].nodes.push(node)
		},
		dragParticipant(state, action) {
			const {
				sourceLevelIndex,
				endLevelIndex,
				endGroupIndex,
				sourceGroupIndex,
				endIndex,
				sourceIndex,
				movedNode,
				replacedNode
			} = action.payload

			state.stage.levels[sourceLevelIndex].groups[sourceGroupIndex].nodes[sourceIndex] = movedNode
			state.stage.levels[endLevelIndex].groups[endGroupIndex].nodes[endIndex] = replacedNode
		},
		updateGroupNodes(state, action) {
			const { levels, levelIndex, groupIndex, nodeIndex, addedNode } = action.payload

			state.stage.levels = levels.map((lvl, lvlIndex) => ({
				...lvl,
				groups: lvl.groups.map((grp, grpIndex) => ({
					...grp,
					nodes: grp.nodes.map((item, itemIndex) => {
						if (((addedNode.playerUid && addedNode.playerUid === item.playerUid)
							|| (addedNode.doubleUid && addedNode.doubleUid === item.doubleUid)
							|| (!addedNode.playerUid && !addedNode.doubleUid && addedNode.name === item.name))) {
							return {
								...item,
								...EMPTY_NODE,
								nodeUid: getNewUid(),
								dependsOnUid: null
							}
						} else if (
							lvlIndex === levelIndex && grpIndex === groupIndex && itemIndex === nodeIndex
						) {
							return {
								...item,
								participant: addedNode.participant,
								playerUid: addedNode.playerUid || null,
								doubleUid: addedNode.doubleUid || null,
								dependsOnUid: addedNode.nodeUid,
								placed: true,
								rating: addedNode.rating,
								name: addedNode.name,
								emptyPlayer: addedNode.emptyPlayer || false
							}
						} else {
							return item
						}
					})
				}))
			}))
		},
		updateGroupName(state, action) {
			const { levelIndex, groupIndex, groupName } = action.payload
			state.stage.levels[levelIndex].groups[groupIndex].name = groupName
		},
		updateLevelName(state, action) {
			const { levelIndex, levelName } = action.payload
			state.stage.levels[levelIndex].name = levelName
		},
		addLevel(state, action) {
			const { levels, level } = action.payload
			let updatedLevels = [...levels]
			updatedLevels.push(level)
			updatedLevels = updateGroupsAndLevelsOrderNumber(updatedLevels)

			state.stage.levels = updatedLevels
		},
		removeLevel(state, action) {
			const { levels, levelIndex} = action.payload
			let updatedLevels = [...levels]

			updatedLevels.splice(levelIndex, 1)
			updatedLevels = updateGroupsAndLevelsOrderNumber(updatedLevels)

			state.stage.levels = updatedLevels
		},
		addGroup(state, action) {
			const { levels, levelIndex, group } = action.payload
			let updatedLevels = [...levels]
			const updatedLevel = {...updatedLevels[levelIndex]}
			const updatedGroups = [...updatedLevel.groups]

			updatedGroups.push(group)
			updatedLevel.groups = updatedGroups
			updatedLevels[levelIndex] = updatedLevel
			updatedLevels = updateGroupsAndLevelsOrderNumber(updatedLevels)

			state.stage.levels = updatedLevels
		},
		updateGroup(state, action) {
			const { levelIndex, groupIndex, participantsMax, type } = action.payload
			state.stage.levels[levelIndex].groups[groupIndex].participants_max = participantsMax
			state.stage.levels[levelIndex].groups[groupIndex].type = type
		},
		removeGroup(state, action) {
			const { levels, levelIndex, groupIndex } = action.payload
			let updatedLevels = [...levels]
			const updatedLevel = {...levels[levelIndex]}

			if (updatedLevel.groups.length < 2) {
				updatedLevels.splice(levelIndex, 1)
			} else {
				const updatedGroups = [...levels[levelIndex].groups]

				updatedGroups.splice(groupIndex, 1)
				updatedLevel.groups = updatedGroups
				updatedLevels[levelIndex] = updatedLevel
			}

			updatedLevels = updateGroupsAndLevelsOrderNumber(updatedLevels)

			state.stage.levels = updatedLevels
		},
		setPlayersList(state, action) {
			state.playersList = action.payload
		},
		setChosenPlayerInList(state, action) {
			state.chosenPlayerInList = action.payload
		},
		setDragState(state, action) {
			state.dragState = action.payload
		},
		setCurrentStageNumber(state, action) {
			setItemInLocalStorage('currentStage', action.payload)
			state.currentStageNumber = action.payload
		}
	}
})

export const {
	setStageData,
	addParticipant,
	updateGroupNodes,
	updateGroupName,
	updateLevelName,
	addLevel,
	addGroup,
	updateGroup,
	removeLevel,
	removeGroup,
	dragParticipant,
	setStageLevels,
	setPlayersList,
	setChosenPlayerInList,
	setDragState,
	setCurrentStageNumber
} = stageSlice.actions
export default stageSlice.reducer