import { memo, useState } from 'react'
import SmoothCollapse from 'react-smooth-collapse'

import './StageBuildGroup.scss'
import { ReactComponent as ArrowDownIcon } from '../../icons/arrow_down.svg'
import { ReactComponent as RoundRobinIcon } from '../../icons/round_robin.svg'
import { ReactComponent as OlympicIcon } from '../../icons/olympic.svg'
import { ReactComponent as OlympicPlusIcon } from '../../icons/olympic_plus.svg'
import { ReactComponent as OlympicThreeIcon } from '../../icons/olympic_three.svg'
import { ReactComponent as NoPlayerIcon } from '../../icons/no_player.svg'
import { ReactComponent as DropOutIcon } from '../../icons/drop_out.svg'
import {
	GROUP_TYPE_OLYMPIC_PLUS,
	GROUP_TYPE_RR,
	GROUP_TYPE_NOPLAYER,
	GROUP_TYPE_DROP_OUT,
	GROUP_TYPE_OLYMPIC,
	GROUP_TYPE_OLYMPIC_THREE
} from '../../utils/constants'
import GroupPlayerEdit from '../GroupPlayerEdit/GroupPlayerEdit'
import { generateGroupOrLevelsName } from '../../utils/functions'

function StageBuildGroup({ levelIndex, groupIndex, group }) {
	const [isNewGroup, setIsNewGroup] = useState(group.new ? true : false)
	const [showGroup, setShowGroup] = useState(isNewGroup)

	// Функция возвращающая количество игроков в Группе в двух вариантах (4 или 3/4)
	function nodesLength() {
		const activeNodes = group.nodes.filter(node => !node.disabled)
		const noNameNode = group?.nodes?.filter((node) => {
			return node?.name !== '---'
		})

		if (noNameNode?.length === group?.nodes?.length) {
			return group?.nodes?.length
		} else {
			return `${noNameNode?.length}/${activeNodes.length}`
		}
	}

	function handleGroupArrow() {
		setIsNewGroup(false)
		setShowGroup(prev => !prev)
	}

	return (
		<>
			<div className="stage-build-group">
				<div
					className={`stage-build-group__header ${showGroup ? 'stage-build-group__header--border' : ''}`}
				>
					<div className="stage-build-group__name-wrapper">
						<p className="stage-build-group__header-name-group">
							{generateGroupOrLevelsName(group.order_number - 1)}
						</p>
					</div>

					<div className="group__header-wrapper">
						{
							group?.type === GROUP_TYPE_RR ?
								<RoundRobinIcon className="round-robin__icon" />
								:
								group?.type === GROUP_TYPE_OLYMPIC_PLUS ?
									<OlympicPlusIcon className="olympic-plus__icon" />
									:
									group?.type === GROUP_TYPE_NOPLAYER ?
										<NoPlayerIcon className="no-player__icon" />
										:
										group?.type === GROUP_TYPE_DROP_OUT ?
											<DropOutIcon className="drop-out__icon" />
											:
											group?.type === GROUP_TYPE_OLYMPIC ?
												<OlympicIcon className="olympic__icon" />
												:
												group?.type === GROUP_TYPE_OLYMPIC_THREE ?
													<OlympicThreeIcon className="olympic-three__icon" />
													:
													null
						}

						<p className="stage-build-group__header-counter">
							{nodesLength()}
						</p>

						<ArrowDownIcon
							className={`arrow-down__icon ${showGroup || isNewGroup ? 'arrow--up' : 'arrow--down'}`}
							onClick={handleGroupArrow}
						/>
					</div>
				</div>

				<SmoothCollapse expanded={showGroup || isNewGroup}>
					<GroupPlayerEdit
						levelIndex={levelIndex}
						groupIndex={groupIndex}
						group={group}
					/>
				</SmoothCollapse>
			</div>
		</>
	)
}

export default memo(StageBuildGroup)