function placeParticipants(playersList, addedNode, replacedNode) {
	return playersList.map(item => {
		if ((item.playerUid && item.playerUid === replacedNode.playerUid)
			|| (item.doubleUid && item.doubleUid === replacedNode.doubleUid)
		) {
			// если uid участников равны в удаляемой ноде и ноде из списка
			return {
				...item,
				placed: false
			}
		} else if ((item.playerUid && item.playerUid === addedNode.playerUid)
			|| (item.doubleUid && item.doubleUid === addedNode.doubleUid)
		) {
			// если uid участников равны в добавляемой ноде и ноде из списка
			return {
				...item,
				placed: true
			}
		} else if (replacedNode.emptyPlayer && ((replacedNode.dependsOnUid && item.nodeUid === replacedNode.dependsOnUid)
			|| (!item.playerUid && !item.doubleUid && replacedNode.name && item.name === replacedNode.name))) {
			// если удаляемая нода пустая и она равна ноде в списке
			return {
				...item,
				placed: false
			}
		} else if (addedNode.emptyPlayer && ((addedNode.dependsOnUid && item.nodeUid === addedNode.dependsOnUid)
			|| (!item.playerUid && !item.doubleUid && addedNode.name && item.name === addedNode.name))) {
			// если добавляемая нода пустая и она равна ноде в списке
			return {
				...item,
				placed: true
			}
		} else {
			return item
		}
	})
}

export {
	placeParticipants
}