import { useMemo, useCallback } from 'react'
import { useTranslation } from 'react-i18next'
import { useSelector, useDispatch } from 'react-redux'
import { useLocation, useNavigate, useParams } from 'react-router'

import './OlympicPlusGridPrint.scss'
import { setMatchData } from '../../redux/matchService/matchSlice'
import { selectTournament } from '../../redux/selectors'
import { TYPE_SINGLES, FINAL_COLUMN_NAME, RESULT_COLUMN_NAME } from '../../utils/constants'
import { getParameters } from '../../utils/functions'

import { formGrid } from '../OlympicPlusGrid/externalFunctions'

function OlympicPlusGrid({ group, auth }) {
	const { t } = useTranslation()
	const navigate = useNavigate()
	const location = useLocation()
	const dispatch = useDispatch()
	const { tournamentParams } = useParams()
	const { tournamentUid } = getParameters(tournamentParams)
	const { type, players, doubles } = useSelector(selectTournament)

	const grid = useMemo(() => {
		return formGrid(group)
	}, [group])

	const participantsMap = useMemo(() => {
		return new Map((players || doubles)?.map(item =>
			[item.uid, item]
		))
	}, [players, doubles])

	function formMatch(match) {
		const { matchData, nodeOne, nodeTwo } = match
		const uidOne = nodeOne?.player_uid || nodeOne?.double_uid
		const uidTwo = nodeTwo?.player_uid || nodeTwo?.double_uid
		let updatedMatch

		if (type === TYPE_SINGLES) {
			const singleOne = participantsMap.get(uidOne)?.formedName
			const singleTwo = participantsMap.get(uidTwo)?.formedName

			updatedMatch = {
				...matchData,
				side1: {
					namePlayer: singleOne,
					nodeUid: matchData.side1_uid
				},
				side2: {
					namePlayer: singleTwo,
					nodeUid: matchData.side2_uid
				},
				uid: matchData?.uid
			}
		} else {
			const doubleOne = {
				firstPlayer: participantsMap.get(uidOne)?.player1.formedName,
				secondPlayer: participantsMap.get(uidOne)?.player2.formedName
			}
			const doubleTwo = {
				firstPlayer: participantsMap.get(uidTwo)?.player1.formedName,
				secondPlayer: participantsMap.get(uidTwo)?.player2.formedName
			}

			updatedMatch = {
				...matchData,
				side1: {
					namePlayer1: doubleOne.firstPlayer,
					namePlayer2: doubleOne.secondPlayer,
					nodeUid: matchData.side1_uid
				},
				side2: {
					namePlayer1: doubleTwo.firstPlayer,
					namePlayer2: doubleTwo.secondPlayer,
					nodeUid: matchData.side2_uid
				},
				uid: matchData?.uid
			}
		}
		return updatedMatch
	}

	function goToMatch(cell) {
		const { matchData, nodeOne, nodeTwo } = cell
		const matchExists = !matchData || (nodeOne?.player_uid && nodeTwo?.player_uid) ||
			(nodeOne?.double_uid && nodeTwo?.double_uid)

		if (!matchExists || !auth) {
			return
		}

		const updatedMatch = formMatch(cell)
		updatedMatch.pathBack = location.pathname
		dispatch(setMatchData(updatedMatch))
		sessionStorage.setItem('match', JSON.stringify(updatedMatch))
		navigate('/' + tournamentUid + '/match')
	}

	function getLoser(match) {
		const noLoser = null

		if (!match.match || !match.matchData.is_finished) {
			return noLoser
		}

		const { matchData } = match
		const { sets, side1_uid, side2_uid } = matchData

		let score1 = 0
		let score2 = 0

		sets.forEach(item => {
			const pointsOne = item.score1 + item.tie_break_score1
			const pointsTwo = item.score2 + item.tie_break_score2

			if (pointsOne > pointsTwo) {
				score1++
			} else if (pointsOne < pointsTwo) {
				score2++
			}
		})

		if (score1 > score2) {
			return side2_uid
		} else if (score1 < score2) {
			return side1_uid
		} else {
			return noLoser
		}
	}

	function getMatch(match) {
		const { nodeOne, nodeTwo } = match
		const uidOne = nodeOne?.player_uid || nodeOne?.double_uid
		const uidTwo = nodeTwo?.player_uid || nodeTwo?.double_uid

		const isLoser = getLoser(match)

		if (type === TYPE_SINGLES) {
			const singleOne = participantsMap.get(uidOne)?.formedName
			const singleTwo = participantsMap.get(uidTwo)?.formedName

			let sideOneClass = 'olympicplus-grid__match-participant--print'
			let sideTwoClass = 'olympicplus-grid__match-participant--print'

			if (isLoser === nodeOne?.uid) {
				sideOneClass = 'olympicplus-grid__match-participant olympicplus-grid__match-loser--print'
			} else if (isLoser === nodeTwo?.uid) {
				sideTwoClass = 'olympicplus-grid__match-participant olympicplus-grid__match-loser--print'
			}

			return (
				<div className="olympicplus-grid__match-sides--print">
					<p className={sideOneClass}>
						{ singleOne }
					</p>

					<p className={sideTwoClass}>
						{ singleTwo }
					</p>
				</div>
			)
		} else {
			const doubleOne = {
				firstPlayer: participantsMap.get(uidOne)?.player1.formedName,
				secondPlayer: participantsMap.get(uidOne)?.player2.formedName
			}
			const doubleTwo = {
				firstPlayer: participantsMap.get(uidTwo)?.player1.formedName,
				secondPlayer: participantsMap.get(uidTwo)?.player2.formedName
			}

			let sideOneClass = 'olympicplus-grid__match-dobles--print'
			let sideTwoClass = 'olympicplus-grid__match-dobles--print'

			if (isLoser === nodeOne?.uid) {
				sideOneClass = 'olympicplus-grid__match-dobles olympicplus-grid__match-loser--print'
			} else if (isLoser === nodeTwo?.uid) {
				sideTwoClass = 'olympicplus-grid__match-dobles olympicplus-grid__match-loser--print'
			}

			return (
				<div className="olympicplus-grid__match-sides--print">
					<div className={sideOneClass}>
						<>
							<p className="olympicplus-grid__match-double-player--print">
								{ doubleOne.firstPlayer }
							</p>

							<p className="olympicplus-grid__match-double-player--print">
								{ doubleOne.secondPlayer }
							</p>
						</>
					</div>

					<div className={sideTwoClass}>
						<>
							<p className="olympicplus-grid__match-double-player--print">
								{ doubleTwo.firstPlayer }
							</p>

							<p className="olympicplus-grid__match-double-player--print">
								{ doubleTwo.secondPlayer }
							</p>
						</>
					</div>
				</div>
			)
		}
	}

	function getParticipantForResult(node) {
		const uid = node?.player_uid || node?.double_uid
		const participant = participantsMap.get(uid)

		if (type === TYPE_SINGLES) {
			return (
				<>
					<p className="olympicplus-grid__result-name--print single">
						{ participant?.formedName }
					</p>
				</>
			)
		} else {
			return (
				<>
					<div className="olympicplus-grid__result-double--print">
						<p className="olympicplus-grid__result-name--print">
							{ participant.player1.formedName }
						</p>

						<p className="olympicplus-grid__result-name--print">
							{ participant.player2.formedName }
						</p>
					</div>
				</>
			)
		}
	}

	function matchStyle(column, columnIndex, cell) {
		const height = type === TYPE_SINGLES ? '64px' : '120px'
		let style = { height }

		if (columnIndex > 0 && column.roundName !== RESULT_COLUMN_NAME) {
			style = {
				...style
			}
		} else if (columnIndex === 0) {
			style = {
				...style
			}
		}

		return style
	}

	const resultBlockStyle = useCallback((cellIndex) => {
		const height = type === TYPE_SINGLES ? '32px' : '60px'

		return {
			backgroundColor: (cellIndex + 1) % 2 === 0 ?
				''
				:
				'var(--palette-live-bg-0-white)',
			height
		}
	}, [type])

	return (
		<div className="olympicplus-grid--print">
			<p className="olympicplus-grid__title--print">
				{ t('Group') } { group.name }
			</p>

			<div className="olympicplus-grid__table-wrapper--print">
				{
					grid.map((column, columnIndex) => (
						<div
							key={columnIndex}
							className="olympicplus-grid__table-container--print"
						>
							<div className="olympicplus-grid__table--print">
								<div className="olympicplus-grid__row-header--print">
									<h5 className="olympicplus-grid__header--print">
										{
											column.roundName !== RESULT_COLUMN_NAME ?
												column.roundName > 1 ?
													`1/${column.roundName}`
													:
													t(FINAL_COLUMN_NAME)
												:
												t(column.roundName)
										}
									</h5>
								</div>

								{
									column.matches.map((cell, cellIndex) => (
										<div
											key={cellIndex}
											className="olympicplus-grid__row--print"
										>
											{
												column.roundName !== RESULT_COLUMN_NAME ?
													<>
														<div
															className="olympicplus-grid__cell--print"
															style={matchStyle(column, columnIndex, cell, cellIndex)}
															onClick={() => goToMatch(cell)}
														>
															<div className="olympicplus-grid__match--print">
																<div className="olympicplus-grid__match-container--print">
																	{
																		getMatch(cell)
																	}
																</div>
															</div>
														</div>
													</>
													:
													<div
														className="olympicplus-grid__cell--print olympicplus-grid__result-container--print"
														style={resultBlockStyle(cellIndex)}
													>
														<div className="olympicplus-grid__result--print">
															{ getParticipantForResult(cell) }

															<p className="olympicplus-grid__result-order--print"></p>
														</div>
													</div>
											}
										</div>
									))
								}
							</div>
						</div>
					))
				}
			</div>
		</div>
	)
}

export default OlympicPlusGrid