import React, { memo, useRef, useMemo, useCallback } from 'react'
import { useParams } from 'react-router-dom'
import { useSelector } from 'react-redux'
import ReactToPrint from 'react-to-print'

import './TournamentStandingPrint.scss'
import { useGetStageQuery } from '../../redux/stageService/stageApiSlice'
import { selectTournament } from '../../redux/selectors'
import { useProcessStageData } from '../../hooks/stageHooks'
import { getParameters } from '../../utils/functions'
import { GROUP_TYPE_RR } from '../../utils/constants'
import RoundRobinGridPrint from '../../extendedComponents/RoundRobinGridPrint/RoundRobinGridPrint'
import OlympicPlusGridPrint from '../../extendedComponents/OlympicPlusGridPrint/OlympicPlusGridPrint'

function TournamentStanding({ auth }) {
	const { tournamentParams, stageNumber } = useParams()
	const { tournamentUid } = getParameters(tournamentParams)
	const { stages_count } = useSelector(selectTournament)
	const componentRef = useRef(null)

	const { data: stageData = {}, status } = useGetStageQuery({
		tournament_uid: tournamentUid,
		stageNumber
	}, {
		skip: !stages_count || stages_count < 1 || stageNumber < 1 || stageNumber > stages_count,
		refetchOnMountOrArgChange: stages_count > 0
	})

	const { stage } = useProcessStageData(stageData, status)

	const stages = useMemo(() => {
		return Array.from({ length: stages_count }, (_, index) => index + 1)
	}, [stages_count])

	const reactToPrintContent = useCallback(() => {
		return componentRef.current
	}, [componentRef])

	console.log(stage?.levels)

	return (
		<>
			<ReactToPrint
				content={reactToPrintContent}
				documentTitle="AwesomeFileName"
				removeAfterPrint
				trigger={() => <button className="print-button">Print this sheet</button>}
				pageStyle="@media print { body { zoom: 0.7; } }"
			/>

			<div style={{display: 'block'}}>
				<main className="tournament-standing" ref={componentRef}>
					{
						stages.length > 1 &&
							<p className="tournament-standing__stage">
								Stage { stageData.order_number }
							</p>
					}

					{
						stage?.levels.map((level, levelIndex) => (
							<React.Fragment key={levelIndex}>
								<div className="tournament-standing__print-wrapper">
									{
										stage?.levels.length > 1 && (
											<p className="tournament-standing__level">
												{ `Level ${ levelIndex + 1 }` }
											</p>
										)
									}

									{
										level?.groups?.map((grp, index) => {
											return (
												<React.Fragment key={index}>
													{
														grp?.type === GROUP_TYPE_RR ?
															<RoundRobinGridPrint
																group={grp}
																auth={auth}
															/>
															:
															<OlympicPlusGridPrint
																group={grp}
																auth={auth}
																stage={stage}
															/>
													}
												</React.Fragment>
											)
										})
									}
								</div>
							</React.Fragment>
						))
					}
				</main>
			</div>
		</>
	)
}

export default memo(TournamentStanding)