import { memo, useState, useCallback, useMemo } from 'react'
import { useTranslation } from 'react-i18next'
import { useDispatch, useSelector } from 'react-redux'
import { useParams, useNavigate } from 'react-router-dom'
import { DragDropContext } from 'react-beautiful-dnd'

import './StageForm.scss'
import StageGroup from '../StageGroup/StageGroup'
import {
	selectTournament,
	selectStage,
} from '../../redux/selectors'
import {
	useRemoveStageMutation,
	useFillStageMutation,
	useFillAutoStageMutation,
	useClearStageMutation,
	useUpdateStageMutation
} from '../../redux/stageService/stageApiSlice'
import { getParameters, checkEquality } from '../../utils/functions'
import {
	setPlayersList,
	setStageData,
	setDragState,
	dragParticipant,
	setChosenPlayerInList,
	setCurrentStageNumber
} from '../../redux/stageService/stageSlice'
import RoundedButton from '../../reusableComponents/RoundedButton/RoundedButton'
import DoubleButton from '../../reusableComponents/DoubleButton/DoubleButton'
import Popup from '../../reusableComponents/Popup/Popup'
import { setTournamentData } from '../../redux/singleTournamentService/singleTournamentSlice'
import NoContent from '../../reusableComponents/NoContent/NoContent'
import { CREATE } from '../../utils/constants'

import {
	dragItems,
	formNodesForRequest,
} from './externalFunctions'

function StageForm({
	stage,
	immutableLevels,
	setStageExists,
	setStageStatus,
	tournamentRefetch,
	stageExists,
	stageStatus
}) {
	const { t } = useTranslation()
	const navigate = useNavigate()
	const dispatch = useDispatch()
	const params = useParams()
	const wildcardValue = params['*']
	const [changeStageParameters] = useUpdateStageMutation()
	const stageData = useSelector(selectStage)
	const { levels } = stageData
	const { tournamentParams, stageNumber } = params
	const [removeStage] = useRemoveStageMutation()
	const [fillStage] = useFillStageMutation()
	const [fillAutoStage] = useFillAutoStageMutation()
	const [fillClearStage] = useClearStageMutation()
	const [removeStageConfirmation, setRemoveStageConfirmation] = useState(false)
	const { tournamentUid } = getParameters(tournamentParams)
	const tournament = useSelector(selectTournament)
	const { type, stages_count, tier } = tournament

	const [requestIsActive, setRequestIsActive] = useState({
		stageRemove: false,
		refillStage: false,
		cleanGroup: false
	})

	const isEquale = useMemo(() => {
		return checkEquality(immutableLevels.current, levels, true)
	}, [immutableLevels, levels])

	const onDragEnd = useCallback((result) => {
		dispatch(setDragState({}))

		if (!result.destination || checkEquality(result.destination, result.source)) {
			return
		}

		const [endLevelIndex, endGroupIndex] = result.destination.droppableId.split('-')
		const { index } = result.destination
		const replacedNode = { ...levels[endLevelIndex]?.groups[endGroupIndex]?.nodes[index] }

		if (replacedNode?.disabled || Object.keys(replacedNode).length === 0) {
			return
		}

		const object = dragItems(result, levels)
		dispatch(dragParticipant(object))
	}, [levels, dispatch])

	// Функция очищающая группы
	async function cleanGroups() {
		setRequestIsActive(prev => { return { ...prev, cleanGroup: true } })

		try {
			const response = await fillClearStage({
				tournament_uid: tournamentUid,
				stageNumber: stageNumber
			}).unwrap()

			if (response?.error) {
				console.log(`ClearStage return error: ${response?.error}`)
			}

			setRequestIsActive(prev => { return { ...prev, cleanGroup: false } })
		} catch (error) {
			console.log(`fillClearStage catch error: ${error}`)
			setRequestIsActive(prev => { return { ...prev, cleanGroup: false } })
		}
	}

	// Функция возвращающая группы по умолчанию
	function returnGroups() {
		const stageState = { ...stage, levels: immutableLevels.current }

		dispatch(setStageData(stageState))
	}

	// Функция удаления этапа
	const handleRemoveStage = useCallback(async () => {
		setRequestIsActive(prev => { return { ...prev, stageRemove: true } })

		try {
			let response = {}

			for (let i = stageNumber - 1; i < stages_count; i++) {
				response = await removeStage({
					tournament_uid: tournamentUid
				}).unwrap()

				if (response?.error) {
					console.log(`Remove stage return error: ${response?.error}`)
				}
			}

			const updatedTournament = {
				...tournament,
				stages_count: response.stages_count
			}

			dispatch(setStageData({}))
			dispatch(setTournamentData(updatedTournament))

			await tournamentRefetch()

			dispatch(setPlayersList([]))
			dispatch(setChosenPlayerInList({}))
			setRemoveStageConfirmation(false)
			dispatch(setCurrentStageNumber(response.stages_count > 0 ? response.stages_count : 1))

			if (response.stages_count < 1) {
				setStageExists(false)
				setStageStatus(CREATE)
			}

			immutableLevels.current = null

			setRequestIsActive(prev => { return { ...prev, stageRemove: false } })

			navigate(`/${tournamentUid}/structure/${response.stages_count > 0 ? response.stages_count : 1}`)
		} catch (error) {
			console.log(`HandleRemoveStage stage catch error ${error}`)
			setRequestIsActive(prev => { return { ...prev, stageRemove: false } })
		}
	}, [
		tournamentUid,
		dispatch,
		stageNumber,
		stages_count,
		removeStage,
		navigate,
		setStageExists,
		setStageStatus,
		tournament,
		tournamentRefetch,
		immutableLevels
	])

	function checkLevelAndGroup(levels, levelsMemory) {
		const levelsMemoryLength = levelsMemory.length
		const levelsLength = levels.length

		if (levelsMemoryLength !== levelsLength) return true

		const groupMemory = levelsMemory.map(level => {
			return level.groups
		})
		const groupMemoryLength = groupMemory[0].length

		const group = levels.map(level => {
			return level.groups
		})
		const groupLength = group[0].length

		if (groupMemoryLength !== groupLength) {
			return true
		} else {
			let isDifferent = false

			levelsMemory.forEach((groups, groupsIndex) => {
				groups.groups.forEach((group, groupIndex) => {
					if ((group.participants_max !== levels[groupsIndex].groups[groupIndex].participants_max)
						|| (group.type !== levels[groupsIndex].groups[groupIndex].type)) {
						isDifferent = true
					}
				})
			})

			return isDifferent
		}
	}

	const handleSaveFormedStage = useCallback(async () => {
		try {
			if (checkLevelAndGroup(levels, immutableLevels.current)) {
				const body = {
					levels: levels
				}

				await changeStageParameters({
					body,
					tournament_uid: tournamentUid,
					stageNumber
				}).unwrap()

				return
			}

			const readyNodes = formNodesForRequest(stage, levels, type)

			await fillStage({
				tournament_uid: tournamentUid,
				stageNumber: stageNumber,
				body: readyNodes
			}).unwrap()
		} catch (error) {
			console.log(error)
		}
	}, [stage, levels, immutableLevels, type, stageNumber,
		tournamentUid, fillStage, changeStageParameters])

	const refillStageSubmit = (async () => {
		setRequestIsActive(prev => { return { ...prev, refillStage: true } })

		try {
			await fillAutoStage({ tournament_uid: tournamentUid, stageNumber }).unwrap()
			setRequestIsActive(prev => { return { ...prev, refillStage: false } })
		}
		catch (e) {
			setRequestIsActive(prev => { return { ...prev, refillStage: false } })
			console.log('refillStageSubmit catch error', e)
		}
	})

	return (
		<div className="stage-form" style={{ marginBottom: !isEquale ? '20px' : '' }}>
			{levels && levels.length > 0 ?
				<>
					<DragDropContext
						onDragEnd={(result) => onDragEnd(result)}
						onDragUpdate={(result) => dispatch(setDragState(result))}
						onBeforeDragStart={(result) => dispatch(setDragState(result))}
					>
						{
							levels?.map((level, levelIndex) =>
								<div
									key={levelIndex}
									className="stage-form__level"
								>
									{
										levels?.length > 1 &&
										<div className="stage-form__level-content">
											<p className="stage-form__level-name">
												{
													level.name === null ?
														`${t('Level').toUpperCase()} ${level?.order_number}`
														:
														level.name
												}
											</p>
										</div>
									}

									{
										level?.groups?.map((group, groupIndex) =>
											<StageGroup
												key={group?.name + groupIndex}
												levelIndex={levelIndex}
												groupIndex={groupIndex}
											/>
										)
									}
								</div>
							)
						}

						{
							levels?.length !== 0 &&
							<div className="stage-form__button-bottom">
								<RoundedButton
									title="Очистить"
									background="grey"
									onClick={cleanGroups}
									loading={requestIsActive.cleanGroup}
								/>

								<RoundedButton
									title="Заполнить"
									background="grey"
									onClick={() => refillStageSubmit()}
									loading={requestIsActive.refillStage}
								/>
							</div>
						}
					</DragDropContext>

					{
						!isEquale && immutableLevels.current &&
						!wildcardValue &&
						<DoubleButton
							titleBig="Сохранить"
							arrow
							typeSmall={'button'}
							typeBig={'button'}
							onClickBig={() => handleSaveFormedStage()}
							onClickSmall={() => returnGroups()}
							fixed
						/>
					}
				</>
				:
				<NoContent
					structure
					tier={tier}
					stageStatus={stageStatus}
					auth
				/>
			}

			{
				stageExists &&
				<button
					className="stage-form__delete-button"
					onClick={() => setRemoveStageConfirmation(true)}
				>
					{t('Remove stage')}
				</button>
			}

			{
				removeStageConfirmation &&
				<Popup title="Это нельзя будет отменить">
					<p className="stage-form__confirmation">
						{t('Are you sure you want to remove stage?')}
					</p>

					<div className="stage-form__confirmation-buttons">
						<RoundedButton
							title={t('Cancel')}
							onClick={() => setRemoveStageConfirmation(false)}
							background="white"
							border
						/>

						<RoundedButton
							title={t('Remove')}
							onClick={handleRemoveStage}
							border
							loading={requestIsActive.stageRemove}
						/>
					</div>
				</Popup>
			}
		</div>
	)
}

export default memo(StageForm)