import React, { useState, useEffect } from 'react'
import { useTranslation } from 'react-i18next'
import { useSelector } from 'react-redux'

import './RoundRobinGridPrint.scss'
import { selectTournament } from '../../redux/selectors'
import { NODE_TYPE_IN, RR_RANKING_SYST_EQUAL, TYPE_DOUBLES } from '../../utils/constants'
import { generateGroupOrLevelsName } from '../../utils/functions'

function RoundRobinGrid({ group }) {
	const { t } = useTranslation()
	const { type, players, doubles, round_robin_ranking_system } = useSelector(selectTournament)
	const [grid, setGrid] = useState([])

	useEffect(() => {
		if (Object.keys(group).length !== 0) {
			const gridArr = group.nodes.flatMap(node => {
				let playerObject

				if (node.type === NODE_TYPE_IN) {
					if (node.double_uid === null && node.player_uid === null) {
						return node
					} else if (players !== null) {
						playerObject = players.find(player => player.uid === node.player_uid)
					} else {
						playerObject = doubles.find(doublesPlayer => doublesPlayer.uid === node.double_uid)
					}

					if (playerObject) {
						return {
							...playerObject,
							nodeUid: node?.uid
						}
					}
				}

				return null
			}).filter(player => player !== null)

			setGrid(gridArr)
		}
		else {
			return
		}
	}, [doubles, players, group])

	return (
		<>
			<div className="roundrobin-grid__wrapper--print">
				<div className="roundrobin-grid__content--print roundrobin-grid__content--width">
					<div className="roundrobin-grid__row--print row-header">
						<div className="roundrobin-grid__header--print group-name__container--print">
							<div className="group-name--print">
								{ generateGroupOrLevelsName(group.order_number - 1)}
							</div>
						</div>
					</div>

					{
						grid?.map((itemVer, indexVertical) => {
							return (
								<div
									className={`roundrobin-grid__row--print ${type === TYPE_DOUBLES ? 'row-doubles' : ''}`}
									key={indexVertical}
								>
									{
										itemVer.player1 ?
											<div className="roundrobin-grid__cell--print participant-name__container--print">
												<div className="participant-name__order--print">
													{ indexVertical + 1 }
												</div>

												{
													itemVer.player1?.formedName ?
														<div className="participant-name__item--print">
															<span>
																{ itemVer.player1.formedName }
															</span>

															<span>
																{ itemVer.player2.formedName }
															</span>
														</div>
														:
														<div className="participant-name__item--print">
															{ itemVer.name }
														</div>
												}
											</div>
											:
											<div className="roundrobin-grid__cell--print participant-name__container--print">
												<div className="participant-name__order--print">
													{ indexVertical + 1 }
												</div>

												<div className="participant-name__item--print">
													{
														itemVer?.formedName ?
															itemVer?.formedName
															:
															itemVer?.name
													}
												</div>
											</div>
									}
								</div>
							)
						})
					}
				</div>

				<div className="roundrobin-grid__content--print">
					<div className="roundrobin-grid__row--print row-header">
						{
							grid?.map((_, index) => {
								return (
									<div
										className="roundrobin-grid__header--print"
										key={index}
									>
										<div className="participant-name__order--print">
											{ index + 1 }
										</div>
									</div>
								)
							})
						}
					</div>

					{
						grid?.map((itemVer, indexVertical) => {
							return (
								<div
									className={`roundrobin-grid__row--print ${type === TYPE_DOUBLES ? 'row-doubles' : ''}`}
									key={indexVertical}
								>
									{
										grid?.map((itemHor, indexHorizontally) =>
											<div
												className={
													`roundrobin-grid__cell--print ${indexVertical === indexHorizontally ?
														'roundrobin-grid__cell--grey'
														:
														''
													}`
												}
												key={indexHorizontally}
											></div>
										)
									}
								</div>
							)
						})
					}
				</div>

				<div className="roundrobin-grid__content--print">
					<div className="roundrobin-grid__row row-header--print">
						<div className="roundrobin-grid__header--print">
							M
						</div>

						<div className="roundrobin-grid__header--print">
							S

							{
								round_robin_ranking_system === RR_RANKING_SYST_EQUAL &&
									<span className="roundrobin-grid__header--inner">
										{ t('between each other') }
									</span>
							}
						</div>

						<div className="roundrobin-grid__header--print">
							G

							{
								round_robin_ranking_system === RR_RANKING_SYST_EQUAL &&
									<span className="roundrobin-grid__header--inner">
										{ t('between each other') }
									</span>
							}
						</div>

						<div className="roundrobin-grid__header--print">
							R
						</div>
					</div>

					{
						grid?.map((_, indexVertical) => {
							return (
								<div
									className={`roundrobin-grid__row--print ${type === TYPE_DOUBLES ? 'row-doubles' : ''}`}
									key={indexVertical}
								>
									<div className="roundrobin-grid__cell--print result-cell__score--print"></div>

									<div className="roundrobin-grid__cell--print"></div>

									<div className="roundrobin-grid__cell--print"></div>

									<div className="roundrobin-grid__cell--print result-cell--print result-cell__score--print"></div>
								</div>
							)
						})
					}
				</div>
			</div>
		</>
	)
}

export default RoundRobinGrid